def runtime(self):
    torch = self.torch()
    hip = getattr(torch.version, "hip", None)
    if self.kind is BackendKind.CUDA and hip:
        raise RuntimeError("CUDA backend cannot execute with HIP-enabled PyTorch")
    if self.kind is BackendKind.HYGON and not hip:
        raise RuntimeError("Hygon backend requires HIP-enabled DTK PyTorch")
    runtime = getattr(torch, self.device_type, None)
    if runtime is None or not runtime.is_available():
        raise RuntimeError(f"{self.kind} is unavailable to this process")
    return runtime

def device(self):
    runtime = self.runtime()
    return self.torch().device(self.device_type, runtime.current_device())

def platform(self) -> str:
    runtime, torch = self.runtime(), self.torch()
    if self.kind is BackendKind.CUDA:
        major, minor = runtime.get_device_capability()
        version = getattr(torch.version, "cuda", None)
        if not version:
            raise RuntimeError("PyTorch does not report its CUDA version")
        return f"nvidia-sm{major}{minor}-cuda{version.split('.')[0]}"
    if self.kind is BackendKind.HYGON:
        properties = runtime.get_device_properties(runtime.current_device())
        architecture = getattr(properties, "gcnArchName", properties.name)
        architecture = safe_name(architecture, default="dcu")
        return f"hygon-{architecture}-hip{torch.version.hip.split('.')[0]}"
    model = safe_name(
        runtime.get_device_name(runtime.current_device()), default="npu"
    )
    return f"ascend-{model}"

def build_options(self, *, compile_flags: Sequence[str] = ()) -> dict[str, Any]:
    """Freeze toolchain and architecture inputs before computing a build key."""
    torch = self.torch()
    if self.kind is BackendKind.ASCEND:
        architecture = os.environ.get(ASCEND_ARCH_ENV)
        if not architecture:
            raise RuntimeError(
                "Set ASCEND_ARCH to the target bisheng NPU architecture"
            )
        home = Path(os.environ.get("ASCEND_HOME_PATH", ASCEND_HOME)).resolve()
        compiler = shutil.which("bisheng")
        if compiler is None:
            candidates = (
                home / "tools/bisheng_compiler/bin/bisheng",
                home / "compiler/ccec_compiler/bin/bisheng",
            )
            compiler = next(
                (str(path) for path in candidates if path.is_file()), None
            )
        if compiler is None:
            raise RuntimeError("AscendC requires CANN bisheng with -x asc support")
        npu = importlib.import_module("torch_npu")
        npu_file = npu.__file__
        if npu_file is None:
            raise RuntimeError("torch_npu does not expose its package location")
        return {
            "architecture": architecture,
            "compiler": str(Path(compiler).resolve()),
            "toolkit": str(home),
            "torch_npu": str(Path(npu_file).resolve().parent),
            "torch_version": torch.__version__,
            "npu_version": getattr(npu, "__version__", "unknown"),
            "abi": int(torch._C._GLIBCXX_USE_CXX11_ABI),
            "pybind_abi": {
                key: value
                for key in ("COMPILER_TYPE", "STDLIB", "BUILD_ABI")
                if (value := getattr(torch._C, f"_PYBIND11_{key}", None))
                is not None
            },
            "cflags": (*CFLAGS, *compile_flags),
        }

    if self.kind is BackendKind.HYGON:
        if not getattr(torch.version, "hip", None):
            raise RuntimeError("Hygon builds require HIP-enabled DTK PyTorch")
        # DTK torch uses cpp_extension's ROCM_HOME convention for hipcc.
        if "ROCM_HOME" not in os.environ:
            home = os.environ.get("HIP_HOME") or os.environ.get("DTK_HOME")
            if home or HIP_HOME.is_dir():
                os.environ["ROCM_HOME"] = str(home or HIP_HOME)
        extension = importlib.import_module("torch.utils.cpp_extension")
        if not extension.IS_HIP_EXTENSION:
            raise RuntimeError(
                "Set ROCM_HOME to DTK before importing torch.utils.cpp_extension"
            )

@dataclass(frozen=True, slots=True)
class Kernel:
    name: str
    problem: ProblemSpec
    source_files: Mapping[str, str] | None = None
    validation: ValidationResult | None = None
    compile_flags: tuple[str, ...] = ()
    language: str | None = field(init=False)
    entry_point: str | None = field(init=False)
    output_style: OutputStyle | None = field(init=False)
    function: Callable[..., Any] | None = field(
        default=None, init=False, repr=False, compare=False
    )

    def __post_init__(self):
        object.__setattr__(self, "name", nonempty(self.name, "kernel name"))
        if not isinstance(self.problem, ProblemSpec):
            raise TypeError("kernel problem must be a ProblemSpec")
        if self.validation is not None and not isinstance(
            self.validation, ValidationResult
        ):
            raise TypeError("kernel validation must be a ValidationResult")
        object.__setattr__(self, "compile_flags", tuple(self.compile_flags))

        sources = {}
        for name, text in mapping(self.source_files or {}, "kernel source_files").items():
            path = relative_source_path(name, "kernel source path")
            if not isinstance(text, str):
                raise TypeError("kernel source contents must be strings")
            if "\x00" in text:
                raise ValueError("kernel sources must not contain NUL bytes")
            sources[path] = text
        object.__setattr__(self, "source_files", sources)
        self.read_build()

    def read_build(self):
        # A source-free placeholder carries only the problem contract. Its build
        # identity stays unknown until the caller supplies sources.
        if not self.source_files:
            for name in ("language", "entry_point", "output_style"):
                object.__setattr__(self, name, None)
            return

        if BUNDLE_CONFIG not in self.source_files:
            backend = get_backend(self.problem.language, self.problem.platform)
            object.__setattr__(self, "language", self.problem.language)
            object.__setattr__(
                self, "entry_point", f"{backend.raw_source}::klineage_launch"
            )
            object.__setattr__(self, "output_style", OutputStyle.DESTINATION)
            return

        config = tomllib.loads(self.source_files[BUNDLE_CONFIG])
        for name in self.source_files:
            if name != BUNDLE_CONFIG and not name.startswith(f"{BUNDLE_SOLUTION}/"):
                raise ValueError(
                    "bundles contain only config.toml and solution/ sources"
                )
        solution = mapping(config[BUNDLE_SOLUTION], "solution metadata")
        for key in ("name", "definition", "author"):
            nonempty(solution[key], f"solution {key}")
        build = mapping(config["build"], "build metadata")
        language = build["language"]
        suffixes = (".py",)
        if language != "python":
            backend = get_backend(self.problem.language, self.problem.platform)
            if language != backend.language:
                raise ValueError(
                    f"build language must be {backend.language} or python for {backend.kind}"
                )
            suffixes = backend.entry_suffixes
        entry = nonempty(build["entry_point"], "build entry_point")
        parts = entry.split("::")
        if entry != build["entry_point"] or len(parts) != 2:
            raise ValueError("entry_point must be relative/source::symbol")
        path, symbol = parts
        relative_source_path(path, "build entry source")
        if PurePosixPath(path).suffix not in suffixes:
            raise ValueError("entry source suffix is incompatible with build language")
        if not symbol.isidentifier() or keyword.iskeyword(symbol):
            raise ValueError("entry symbol must be an identifier")
        destination = build.get("destination_passing_style", False)
        if type(destination) is not bool:
            raise TypeError("destination_passing_style must be a boolean")
        object.__setattr__(self, "language", language)
        object.__setattr__(self, "entry_point", entry)
        object.__setattr__(
            self,
            "output_style",
            OutputStyle.DESTINATION if destination else OutputStyle.RETURN,
        )
        if self.source_path not in self.source_files:
            raise ValueError(f"missing entry source: {self.source_path}")
        nonempty(self.source_files[self.source_path], "bundle entry source")

    @property
    def source_path(self) -> str:
        path = self.entry_point.split("::")[0]
        return (
            f"{BUNDLE_SOLUTION}/{path}" if BUNDLE_CONFIG in self.source_files else path
        )

    @property
    def symbol(self) -> str:
        return self.entry_point.split("::")[1]

    @classmethod
    @agent_function
    def from_sources(
        cls,
        source_files: Mapping[str, str],
        problem: ProblemSpec,
        *,
        name: str | None = None,
        build_root: Path = BUILD_DIRECTORY,
