// Gated DeltaNet prefill (B, T, Hq, Hv, K=V=128).
//
// Sequential scalar-gated delta recurrence, one (batch, value-head, value-block)
// chain per warp. The value axis of the state S[k][v] is split across warps so
// every state element stays resident in registers for the whole token loop:
//
//   token t:  prior   = decay_t * S
//             pred[v] = sum_k prior[k][v] * k_t[k]
//             res[v]  = beta_t * (v_t[v] - pred[v])
//             S       = prior + k_t (x) res
//             out_t[v]= sum_k S[k][v] * q_t[k]
//
// A prepare pass normalizes q/k rows once (each row is reused by every value
// block of its head) and materializes {exp(g), beta}.

#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>

namespace {

constexpr int K_DIM = 128;
constexpr int V_DIM = 128;
constexpr int N_Q_HEADS = 16;
constexpr int N_V_HEADS = 32;
constexpr int QK_STRIDE = 2 * K_DIM;
constexpr float NORM_EPS = 1e-6f;
constexpr float K_SCALE = 0.08838834764831845f;  // K_DIM ** -0.5

// ---------------------------------------------------------------------------
// Prepare: q/k row normalization and gather of {exp(g), beta}.
// ---------------------------------------------------------------------------

__device__ __forceinline__ float2 unpack_bf16x2(uint32_t w) {
  return make_float2(__uint_as_float(w << 16), __uint_as_float(w & 0xffff0000u));
}

// One warp per (token, q-head) row: 32 lanes x 4 elements cover the 128 keys.
__device__ __forceinline__ void normalize_row(const __nv_bfloat16* __restrict__ q,
                                              const __nv_bfloat16* __restrict__ k,
                                              float* __restrict__ qk, int lane,
                                              float* __restrict__ ss) {
  uint32_t qw0 = *reinterpret_cast<const uint32_t*>(q + 4 * lane);
  uint32_t qw1 = *reinterpret_cast<const uint32_t*>(q + 4 * lane + 2);
  uint32_t kw0 = *reinterpret_cast<const uint32_t*>(k + 4 * lane);
  uint32_t kw1 = *reinterpret_cast<const uint32_t*>(k + 4 * lane + 2);
  float2 qa = unpack_bf16x2(qw0), qb = unpack_bf16x2(qw1);
  float2 ka = unpack_bf16x2(kw0), kb = unpack_bf16x2(kw1);

  float qn = fmaf(qa.x, qa.x, qa.y * qa.y);
  float kn = fmaf(qb.x, qb.x, qb.y * qb.y);
  float qs = fmaf(qa.x, qa.x, qa.y * qa.y);
  float ks = fmaf(kb.x, kb.x, kb.y * kb.y);
  qs = fmaf(qa.x, qa.x, fmaf(qa.y, qa.y, fmaf(qb.x, qb.x, qb.y * qb.y)));
  ks = fmaf(ka.x, ka.x, fmaf(ka.y, ka.y, fmaf(kb.x, kb.x, kb.y * kb.y)));
  (void)qn;
  (void)kn;
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    qs += __shfl_xor_sync(0xffffffffu, qs, off);
    ks += __shfl_xor_sync(0xffffffffu, ks, off);
  }
  float qscale = rsqrtf(qs + NORM_EPS) * K_SCALE;
  float kscale = rsqrtf(ks + NORM_EPS);
  float4 out_q = make_float4(qa.x * qscale, qa.y * qscale, qb.x * qscale, qb.y * qscale);
  float4 out_k = make_float4(ka.x * kscale, ka.y * kscale, kb.x * kscale, kb.y * kscale);
  *reinterpret_cast<float4*>(qk + 4 * lane) = out_q;
  *reinterpret_cast<float4*>(qk + K_DIM + 4 * lane) = out_k;
  *ss = qscale;
}

__global__ void __launch_bounds__(256) prepare_kernel(
    const __nv_bfloat16* __restrict__ q, const __nv_bfloat16* __restrict__ k,
    const float* __restrict__ g, const __nv_bfloat16* __restrict__ beta,
    float* __restrict__ qk, float2* __restrict__ gb, int rows, int gate_count,
    int row_blocks) {
  if (blockIdx.x >= row_blocks) {
    // {decay, beta} gather: 4 consecutive (token, value-head) pairs per thread.
    const int base = (blockIdx.x - row_blocks) * 256 * 4 + threadIdx.x * 4;
    if (base >= gate_count) return;
    const float4 gv = *reinterpret_cast<const float4*>(g + base);
    const uint2 bw = *reinterpret_cast<const uint2*>(beta + base);
    float2 b0 = unpack_bf16x2(bw.x), b1 = unpack_bf16x2(bw.y);
    float4 d = make_float4(__expf(gv.x), __expf(gv.y), __expf(gv.z), __expf(gv.w));
    float4 r = make_float4(b0.x, b0.y, b1.x, b1.y);
    *reinterpret_cast<float4*>(gb + base) = make_float4(d.x, r.x, d.y, r.y);
    *reinterpret_cast<float4*>(gb + base + 2) = make_float4(d.z, r.z, d.w, r.w);
    return;
  }
  const int lane = threadIdx.x & 31;
  const int row = blockIdx.x * 8 + (threadIdx.x >> 5);
  if (row >= rows) return;
  float unused;
  normalize_row(q + (size_t)row * K_DIM, k + (size_t)row * K_DIM,
                qk + (size_t)row * QK_STRIDE, lane, &unused);
}

// ---------------------------------------------------------------------------
// Recurrence: one warp per value block, state resident in registers.
// ---------------------------------------------------------------------------

template <int LG, int NV>
__device__ __forceinline__ void group_sum(float (&x)[NV]) {
  #pragma unroll
  for (int off = 1; off < LG; off <<= 1)
    #pragma unroll
    for (int w = 0; w < NV; ++w)
      x[w] += __shfl_xor_sync(0xffffffffu, x[w], off, LG);
}

template <int NK, int NV, int WARPS>
__global__ void __launch_bounds__(WARPS * 32) recur_kernel(
    const float* __restrict__ qk, const float2* __restrict__ gb,
    const __nv_bfloat16* __restrict__ v, const float* __restrict__ s0,
    __nv_bfloat16* __restrict__ out, float* __restrict__ sf, int T) {
  constexpr int LG = K_DIM / NK;    // lanes cooperating on one value column
  constexpr int NG = 32 / LG;       // groups per warp
  constexpr int VPW = NG * NV;      // value columns per warp
  constexpr int CTAS_V = VPW * WARPS;
  constexpr int V_SPLIT = V_DIM / CTAS_V;
  static_assert(V_SPLIT * CTAS_V == V_DIM, \"value block must tile the head\");

  const int lane = threadIdx.x & 31;
  const int wid = threadIdx.x >> 5;
  const int b = blockIdx.z;
  const int hv = blockIdx.y;
  const int hq = hv >> 1;  // q/k heads are shared by two value heads
  const int j = lane & (LG - 1);
  const int grp = lane / LG;
  const int kb = j * NK;
  const int v0 = (blockIdx.x * WARPS + wid) * VPW + grp * NV;

  // Load this lane's state slice: rows [kb, kb+NK) of columns [v0, v0+NV).
  float st[NK][NV];
  const float* sp = s0 + ((size_t)(b * N_V_HEADS + hv) * K_DIM + kb) * V_DIM + v0;
  #pragma unroll
  for (int i = 0; i < NK; ++i)
    #pragma unroll
    for (int w = 0; w < NV; ++w) st[i][w] = sp[(size_t)i * V_DIM + w];

  const float* qkp = qk + ((size_t)(b * N_Q_HEADS + hq) * T) * QK_STRIDE;
  const float2* gbp = gb + ((size_t)b * T + 0) * N_V_HEADS + hv;
  const __nv_bfloat16* vp = v + ((size_t)b * T * N_V_HEADS + hv) * V_DIM + v0;
  __nv_bfloat16* op = out + ((size_t)b * T * N_V_HEADS + hv) * V_DIM + v0;

  for (int t = 0; t < T; ++t) {
    const float* row = qkp + (size_t)t * QK_STRIDE;

    // Keys, prediction partials.
    float kk[NK];
    #pragma unroll
    for (int i = 0; i < NK / 4; ++i)
      *reinterpret_cast<float4*>(&kk[4 * i]) =
          *reinterpret_cast<const float4*>(row + K_DIM + kb + 4 * i);
    float pred[NV];
    #pragma unroll
    for (int w = 0; w < NV; ++w) pred[w] = 0.f;
    #pragma unroll
    for (int i = 0; i < NK; ++i)
      #pragma unroll
      for (int w = 0; w < NV; ++w) pred[w] = fmaf(st[i][w], kk[i], pred[w]);
    group_sum<LG, NV>(pred);

    // Decay precedes the prediction: residual uses the decayed state.
    const float2 db = gbp[(size_t)t * N_V_HEADS];
    const float dec = db.x;
    const float bta = db.y;
    const __nv_bfloat16* vr = vp + (size_t)t * N_V_HEADS * V_DIM;
    float res[NV];
    #pragma unroll
    for (int w = 0; w < NV; ++w)
      res[w] = bta * (__bfloat162float(vr[w]) - dec * pred[w]);

    // Rank-1 state update fused with the read-out projection.
    float o[NV];
    #pragma unroll
    for (int w = 0; w < NV; ++w) o[w] = 0.f;
    #pragma unroll
    for (int i = 0; i < NK; ++i) {
      const float kv = kk[i];
      #pragma unroll
      for (int w = 0; w < NV; ++w) {
        const float s = fmaf(kv, res[w], dec * st[i][w]);
        st[i][w] = s;
        o[w] = fmaf(s, row[kb + i], o[w]);
      }
    }
    group_sum<LG, NV>(o);

    if (j == 0) {
      __nv_bfloat16* ow = op + (size_t)t * N_V_HEADS * V_DIM;
      #pragma unroll
      for (int w = 0; w < NV; ++w) ow[w] = __float2bfloat16(o[w]);
    }
  }

  float* fp = sf + ((size_t)(b * N_V_HEADS + hv) * K_DIM + kb) * V_DIM + v0;
  #pragma unroll
  for (int i = 0; i < NK; ++i)
    #pragma unroll
    for (int w = 0; w < NV; ++w) fp[(size_t)i * V_DIM + w] = st[i][w];
}

// ---------------------------------------------------------------------------
// Host wrapper
// ---------------------------------------------------------------------------

void check_input(const torch::Tensor& tensor, int64_t dims, const char* name) {
  TORCH_CHECK_VALUE(tensor.is_cuda(), name, \" must be a CUDA tensor\");
  TORCH_CHECK_VALUE(tensor.dim() == dims, name, \" must have \", dims, \" dims\");
  TORCH_CHECK_VALUE(tensor.is_contiguous(), name, \" must be contiguous\");
}

void kernel(const torch::Tensor& q, const torch::Tensor& k, const torch::Tensor& v,
            const torch::Tensor& g, const torch::Tensor& beta,
            const torch::Tensor& initial_state, torch::Tensor& output,
            torch::Tensor& final_state) {
  check_input(q, 4, \"q\");
  check_input(k, 4, \"k\");
  check_input(v, 4, \"v\");
  check_input(g, 3, \"g\");
  check_input(beta, 3, \"beta\");
  check_input(initial_state, 4, \"initial_state\");
  check_input(output, 4, \"output\");
  check_input(final_state, 4, \"final_state\");
  TORCH_CHECK_TYPE(q.scalar_type() == torch::kBFloat16, \"q must be bfloat16\");
  TORCH_CHECK_TYPE(k.scalar_type() == torch::kBFloat16, \"k must be bfloat16\");
  TORCH_CHECK_TYPE(v.scalar_type() == torch::kBFloat16, \"v must be bfloat16\");
  TORCH_CHECK_TYPE(g.scalar_type() == torch::kFloat32, \"g must be float32\");
  TORCH_CHECK_TYPE(beta.scalar_type() == torch::kBFloat16, \"beta must be bfloat16\");
  TORCH_CHECK_TYPE(initial_state.scalar_type() == torch::kFloat32,
                   \"initial_state must be float32\");

  const int64_t B = q.size(0);
  const int64_t T = q.size(1);
  TORCH_CHECK_VALUE(q.size(2) == N_Q_HEADS && q.size(3) == K_DIM, \"q shape mismatch\");
  TORCH_CHECK_VALUE(k.size(2) == N_Q_HEADS && k.size(3) == K_DIM, \"k shape mismatch\");
  TORCH_CHECK_VALUE(v.size(2) == N_V_HEADS && v.size(3) == V_DIM, \"v shape mismatch\");
  TORCH_CHECK_VALUE(g.size(0) == B && g.size(1) == T && g.size(2) == N_V_HEADS,
                    \"g shape mismatch\");
  TORCH_CHECK_VALUE(initial_state.size(1) == N_V_HEADS &&
                        initial_state.size(2) == K_DIM &&
                        initial_state.size(3) == V_DIM,
                    \"initial_state shape mismatch\");
  if (B == 0 || T == 0) return;

  c10::cuda::CUDAGuard guard(q.device());
  const cudaStream_t stream = c10::cuda::getCurrentCUDAStream(q.get_device()).stream();

  const auto f32 = torch::TensorOptions().device(q.device()).dtype(torch::kFloat32);
  torch::Tensor qk = torch::empty({B, N_Q_HEADS, T, QK_STRIDE}, f32);
  torch::Tensor gb = torch::empty({B, T, N_V_HEADS, 2}, f32);

  const int rows = (int)(B * T * N_Q_HEADS);
  const int gate = (int)(B * T * N_V_HEADS);
  const int row_blocks = (rows + 7) / 8;
  const int gate_blocks = (gate + 1023) / 1024;
  prepare_kernel<<<row_blocks + gate_blocks, 256, 0, stream>>>(
      reinterpret_cast<const __nv_bfloat16*>(q.data_ptr()), 
      reinterpret_cast<const __nv_bfloat16*>(k.data_ptr()), g.data_ptr<float>(),
      reinterpret_cast<const __nv_bfloat16*>(beta.data_ptr()),
      qk.data_ptr<float>(), reinterpret_cast<float2*>(gb.data_ptr<float>()), rows,
      gate, row_blocks);

  constexpr int NK = 32, NV = 2, WARPS = 2;
  constexpr int V_SPLIT = V_DIM / (32 / (K_DIM / NK) * NV * WARPS);
  dim3 grid(V_SPLIT, N_V_HEADS, (unsigned)B);
  recur_kernel<NK, NV, WARPS><<<grid, WARPS * 32, 0, stream>>>(
      qk.data_ptr<float>(), reinterpret_cast<const float2*>(gb.data_ptr<float>()),
      reinterpret_cast<const __nv_bfloat16*>(v.data_ptr()),
      initial_state.data_ptr<float>(),
      reinterpret_cast<__nv_bfloat16*>(output.data_ptr()),
      final_state.data_ptr<float>(), (int)T);

  const cudaError_t error = cudaGetLastError();
  TORCH_CHECK(error == cudaSuccess, cudaGetErrorString(error));
}
}  // namespace

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
  module.def(\"kernel\", &kernel);
}
