    // {decay, beta} gather: 4 consecutive (token, value-head) pairs per thread.
    const int base = (blockIdx.x - row_blocks) * 256 * 4 + threadIdx.x * 4;
    if (base >= gate_count) return;
    const float4 gv = *reinterpret_cast<const float4*>(g + base);
    const uint2 bw = *reinterpret_cast<const uint2*>(beta + base);
    float2 b0 = unpack_bf16x2(bw.x), b1 = unpack_bf16x2(bw.y);
    float4 d = make_float4(__expf(gv.x), __expf(gv.y), __expf(gv.z), __expf(gv.w));
    float4 r = make_float4(b0.x, b0.y, b1.x, b1.y);
    *reinterpret_cast<float4*>(gb + base) = make_float4(d.x, r.x, d.y, r.y);
    *reinterpret_cast<float4*>(gb + base + 2) = make_float4(d.z, r.z, d.w, r.w);
