      #pragma unroll
      for (int c = 0; c < ACC; ++c)
        #pragma unroll
        for (int w = 0; w < NV; ++w) pp[c][w] = 0.f;
      #pragma unroll
      for (int i = 0; i < NK; ++i)
        #pragma unroll
        for (int w = 0; w < NV; ++w)
