            *reinterpret_cast<const float4*>(row + K_DIM + kb + 4 * i);
      float pp[ACC][NV];
      #pragma unroll
      for (int c = 0; c < ACC; ++c)
        #pragma unroll
        for (int w = 0; w < NV; ++w) pp[c][w] = 0.f;

