// Gated DeltaNet prefill (B, T, Hq=16, Hv=32, K=V=128).
//
// Sequential scalar-gated delta recurrence, one (batch, value-head, value-block)
// chain per warp. The value axis of the state S[k][v] is split across warps so
// every state element stays resident in registers for the whole token loop:
//
//   token t:  prior    = decay_t * S
//             pred[v]  = sum_k prior[k][v] * k_t[k]
//             res[v]   = beta_t * (v_t[v] - pred[v])
//             S        = prior + k_t (x) res
//             out_t[v] = sum_k S[k][v] * q_t[k]
//
// The token loop is purely sequential, so the operand stream is staged into
// shared memory with cp.async a few tokens ahead: k/q rows are 1 KiB per token,
// far larger than the register file can shadow.

#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_bf16.h>
#include <cuda_pipeline.h>
#include <cuda_runtime.h>

namespace {

constexpr int K_DIM = 128;
constexpr int V_DIM = 128;
constexpr int N_Q_HEADS = 16;
constexpr int N_V_HEADS = 32;
constexpr int QK_STRIDE = 2 * K_DIM;
constexpr float NORM_EPS = 1e-6f;
constexpr float K_SCALE = 0.08838834764831845f;  // K_DIM ** -0.5

constexpr int PREP_WARPS = 8;                     // rows per prepare block
constexpr int PREP_THREADS = 32 * PREP_WARPS;
constexpr int GATE_PER_BLOCK = PREP_THREADS * 4;  // (token, head) pairs per block

constexpr int ACC = 4;  // split accumulators shorten the FMA dependency chain

// ---------------------------------------------------------------------------
// Prepare: q/k row normalization and gather of {exp(g), beta}.
// ---------------------------------------------------------------------------

__device__ __forceinline__ float2 unpack_bf16x2(uint32_t word) {
  // bf16 is the high half of an fp32: shifting reinterprets it exactly.
  return make_float2(__uint_as_float(word << 16), __uint_as_float(word & 0xffff0000u));
}

// One warp per (token, q-head) row; 32 lanes x 4 elements cover the 128 keys.
__device__ __forceinline__ void normalize_row(const __nv_bfloat16* __restrict__ q,
                                              const __nv_bfloat16* __restrict__ k,
                                              float* __restrict__ qk, int lane) {
  const uint32_t qw0 = *reinterpret_cast<const uint32_t*>(q + 4 * lane);
  const uint32_t qw1 = *reinterpret_cast<const uint32_t*>(q + 4 * lane + 2);
  const uint32_t kw0 = *reinterpret_cast<const uint32_t*>(k + 4 * lane);
  const uint32_t kw1 = *reinterpret_cast<const uint32_t*>(k + 4 * lane + 2);
  const float2 qa = unpack_bf16x2(qw0), qb = unpack_bf16x2(qw1);
  const float2 ka = unpack_bf16x2(kw0), kb = unpack_bf16x2(kw1);

  float qs = fmaf(qa.x, qa.x, fmaf(qa.y, qa.y, fmaf(qb.x, qb.x, qb.y * qb.y)));
  float ks = fmaf(ka.x, ka.x, fmaf(ka.y, ka.y, fmaf(kb.x, kb.x, kb.y * kb.y)));
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    qs += __shfl_xor_sync(0xffffffffu, qs, off);
    ks += __shfl_xor_sync(0xffffffffu, ks, off);
  }
  const float qscale = rsqrtf(qs + NORM_EPS) * K_SCALE;
  const float kscale = rsqrtf(ks + NORM_EPS);
  *reinterpret_cast<float4*>(qk + 4 * lane) =
      make_float4(qa.x * qscale, qa.y * qscale, qb.x * qscale, qb.y * qscale);
  *reinterpret_cast<float4*>(qk + K_DIM + 4 * lane) =
      make_float4(ka.x * kscale, ka.y * kscale, kb.x * kscale, kb.y * kscale);
}

__global__ void __launch_bounds__(PREP_THREADS) prepare_kernel(
    const __nv_bfloat16* __restrict__ q, const __nv_bfloat16* __restrict__ k,
    const float* __restrict__ g, const __nv_bfloat16* __restrict__ beta,
    float* __restrict__ qk, float2* __restrict__ gb, int rows, int gate_count,
    int row_blocks) {
  if (blockIdx.x >= row_blocks) {
    // {decay, beta} gather: 4 consecutive (token, value-head) pairs per thread.
    const int base = (blockIdx.x - row_blocks) * GATE_PER_BLOCK + threadIdx.x * 4;
    if (base >= gate_count) return;
    const float4 gv = *reinterpret_cast<const float4*>(g + base);
    const uint2 bw = *reinterpret_cast<const uint2*>(beta + base);
    const float2 b0 = unpack_bf16x2(bw.x), b1 = unpack_bf16x2(bw.y);
    const float4 d =
        make_float4(__expf(gv.x), __expf(gv.y), __expf(gv.z), __expf(gv.w));
    *reinterpret_cast<float4*>(gb + base) = make_float4(d.x, b0.x, d.y, b0.y);
    *reinterpret_cast<float4*>(gb + base + 2) = make_float4(d.z, b1.x, d.w, b1.y);
    return;
  }
  const int row = blockIdx.x * PREP_WARPS + (threadIdx.x >> 5);
  if (row >= rows) return;
  normalize_row(q + (size_t)row * K_DIM, k + (size_t)row * K_DIM,
                qk + (size_t)row * QK_STRIDE, threadIdx.x & 31);
}

// ---------------------------------------------------------------------------
// Recurrence: one warp per value block, state resident in registers.
// ---------------------------------------------------------------------------

template <int LG, int NV>
__device__ __forceinline__ void group_sum(float (&x)[NV]) {
  #pragma unroll
  for (int off = 1; off < LG; off <<= 1)
    #pragma unroll
    for (int w = 0; w < NV; ++w)
      x[w] += __shfl_xor_sync(0xffffffffu, x[w], off, LG);
}

// Stage one token batch: q/k row (1 KiB), value slice, gate scalars.
template <int CTAS_V, int TOK, int THREADS>
__device__ __forceinline__ void stage_issue(float (*s_qk)[QK_STRIDE],
                                            __nv_bfloat16* s_v, float2* s_g,
                                            const float* __restrict__ qk,
                                            const __nv_bfloat16* __restrict__ vts,
                                            const float2* __restrict__ gts,
                                            int hq, int cta_v, int n_tok) {
  constexpr int QK_CHUNKS = QK_STRIDE / 4;          // 16-byte chunks per row
  constexpr int V_CHUNKS = CTAS_V * sizeof(__nv_bfloat16) / 16;
  const int tid = threadIdx.x;

  // q/k rows: TOK x 64 chunks, contiguous global addresses.
  #pragma unroll
  for (int j = 0; j < TOK; ++j) {
    const size_t base = ((size_t)n_tok * N_Q_HEADS + hq) * QK_STRIDE;
    for (int c = tid; c < QK_CHUNKS; c += THREADS)
      __pipeline_memcpy_async(&s_qk[j][4 * c], qk + base + 4 * c, 16);
  }
  // value slice: TOK x V_CHUNKS contiguous 16-byte pieces.
  #pragma unroll
  for (int j = 0; j < TOK; ++j) {
    const size_t base = ((size_t)n_tok * N_V_HEADS) * V_DIM + cta_v;
    for (int c = tid; c < V_CHUNKS; c += THREADS)
      __pipeline_memcpy_async(s_v + (j * CTAS_V + 8 * c), vts + base + 8 * c, 16);
  }
  // gate scalars: 8 bytes per token.
  if (tid < TOK)
    __pipeline_memcpy_async(s_g + tid, gts + (size_t)tid * N_V_HEADS, 8);
}

template <int NK, int NV, int WARPS, int TOK, int STAGES>
__global__ void __launch_bounds__(WARPS * 32) recur_kernel(
    const float* __restrict__ qk, const float2* __restrict__ gb,
    const __nv_bfloat16* __restrict__ v, const float* __restrict__ s0,
    __nv_bfloat16* __restrict__ out, float* __restrict__ sf, int T) {
  constexpr int LG = K_DIM / NK;  // lanes cooperating on one value column
  constexpr int NG = 32 / LG;     // groups per warp
  constexpr int VPW = NG * NV;    // value columns per warp
  constexpr int CTAS_V = VPW * WARPS;
  constexpr int V_SPLIT = V_DIM / CTAS_V;
  constexpr int THREADS = WARPS * 32;
  static_assert(V_SPLIT * CTAS_V == V_DIM, \"value block must tile the head\");
  static_assert(QK_STRIDE % 4 == 0 && (CTAS_V * 2) % 16 == 0,
                \"16-byte async copies\");

  __shared__ float s_qk[STAGES][TOK][QK_STRIDE];
  __shared__ __nv_bfloat16 s_v[STAGES][TOK][CTAS_V];
  __shared__ float2 s_g[STAGES][TOK];

  const int lane = threadIdx.x & 31;
  const int wid = threadIdx.x >> 5;
  const int b = blockIdx.z;
  const int hv = blockIdx.y;
  const int hq = hv >> 1;  // two value heads share one q/k head
  const int j = lane & (LG - 1);
  const int grp = lane / LG;
  const int kb = j * NK;
  const int cta_v = blockIdx.x * CTAS_V;
  const int vl = wid * VPW + grp * NV;  // this lane's first column in the block

  // This lane owns rows [kb, kb+NK) of value columns [vl, vl+NV).
  float st[NK][NV];
  const float* sp = s0 + ((size_t)(b * N_V_HEADS + hv) * K_DIM + kb) * V_DIM +
                    cta_v + vl;
  #pragma unroll
  for (int i = 0; i < NK; ++i)
    #pragma unroll
    for (int w = 0; w < NV; ++w) st[i][w] = sp[(size_t)i * V_DIM + w];

  const float* qk_head = qk + ((size_t)b * T * N_Q_HEADS + hq) * QK_STRIDE;
  const __nv_bfloat16* v_head =
      v + ((size_t)b * T * N_V_HEADS + hv) * V_DIM + cta_v;
  const float2* g_head = gb + (size_t)b * T * N_V_HEADS + hv;

  const int n_stage = (T + TOK - 1) / TOK;
  #pragma unroll
  for (int s = 0; s < STAGES - 1; ++s) {
    if (s < n_stage) {
      stage_issue<CTAS_V, TOK, THREADS>(s_qk[s], s_v[s], s_g[s], qk_head, v_head,
                                        g_head, hq, cta_v, s * TOK);
      __pipeline_commit();
    }
  }

  for (int s = 0; s < n_stage; ++s) {
    const int cur = s % STAGES;
    const int nxt = s + STAGES - 1;
    if (nxt < n_stage) {
      stage_issue<CTAS_V, TOK, THREADS>(s_qk[cur == STAGES - 1 ? 0 : cur + 1],
                                        s_v[cur == STAGES - 1 ? 0 : cur + 1],
                                        s_g[cur == STAGES - 1 ? 0 : cur + 1],
                                        qk_head, v_head, g_head, hq, cta_v,
                                        nxt * TOK);
      __pipeline_commit();
    } else {
      __pipeline_commit();
    }
    __pipeline_wait_prior(STAGES - 1);
    __syncthreads();

    const int t_end = min(TOK, T - s * TOK);
    for (int u = 0; u < t_end; ++u) {
      const float2 db = s_g[cur][u];
      const float dec = db.x;
      const float bta = db.y;
      const float* row = s_qk[cur][u];

      // Keys, then prediction partials split over four accumulators.
      float kk[NK];
      #pragma unroll
      for (int i = 0; i < NK / 4; ++i)
        *reinterpret_cast<float4*>(&kk[4 * i]) =
            *reinterpret_cast<const float4*>(row + K_DIM + kb + 4 * i);
      float pp[ACC][NV];
      #pragma unroll
      for (int c = 0; c < ACC; ++c)
        #pragma unroll
        for (int w = 0; w < NV; ++w) pp[c][w] = 0.f;
      #pragma unroll
      for (int i = 0; i < NK; ++i)
        #pragma unroll
        for (int w = 0; w < NV; ++w)
          pp[i & (ACC - 1)][w] = fmaf(st[i][w], kk[i], pp[i & (ACC - 1)][w]);
      #pragma unroll
      for (int c = 1; c < ACC; ++c)
        #pragma unroll
        for (int w = 0; w < NV; ++w) pp[0][w] += pp[c][w];
      group_sum<LG, NV>(pp[0]);

      // Decay precedes the prediction; the residual drives the rank-1 update.
      const float2 vv = *reinterpret_cast<const float2*>(
          s_v[cur][u] + vl);  // NV <= 2 packed into one word
      float res[NV];
      #pragma unroll
      for (int w = 0; w < NV; ++w)
        res[w] = bta * (__bfloat162float(reinterpret_cast<const __nv_bfloat16*>(
                            &vv)[w]) -
                        dec * pp[0][w]);

      // Rank-1 state update fused with the read-out projection.
      float oo[ACC][NV];
      #pragma unroll
      for (int c = 0; c < ACC; ++c)
        #pragma unroll
        for (int w = 0; w < NV; ++w) oo[c][w] = 0.f;
      #pragma unroll
      for (int i = 0; i < NK; ++i) {
        const float kv = kk[i];
        #pragma unroll
        for (int w = 0; w < NV; ++w) {
          const float sn = fmaf(kv, res[w], dec * st[i][w]);
          st[i][w] = sn;
          oo[i & (ACC - 1)][w] = fmaf(sn, row[kb + i], oo[i & (ACC - 1)][w]);
        }
      }
      #pragma unroll
      for (int c = 1; c < ACC; ++c)
        #pragma unroll
        for (int w = 0; w < NV; ++w) oo[0][w] += oo[c][w];
      group_sum<LG, NV>(oo[0]);

      if (j == 0) {
        __nv_bfloat16* ow = out + ((size_t)b * T * N_V_HEADS + hv) * V_DIM +
