  TORCH_CHECK_VALUE(k.size(2) == N_Q_HEADS && k.size(3) == K_DIM, "k shape mismatch");
  TORCH_CHECK_VALUE(v.size(2) == N_V_HEADS && v.size(3) == V_DIM, "v shape mismatch");

