                    "g shape mismatch");
  TORCH_CHECK_VALUE(initial_state.size(0) == B &&
                        initial_state.size(1) == N_V_HEADS &&
                        initial_state.size(2) == K_DIM &&
                        initial_state.size(3) == V_DIM,
